  "Your running activity needs a stop condition for this queued job to begin automatically.": "Sıradaki işin otomatik başlaması için çalışan etkinliğine bir durdurma koşulu koymalısın.",
  "Stop current activity after 2 hours": "Mevcut etkinliği 2 saat sonra durdur",
  "Stop current activity after 4 hours": "Mevcut etkinliği 4 saat sonra durdur",
