  "The queue will NOT advance automatically until your current activity stops or an applicable idle rule triggers.": "Mevcut etkinlik durmadan veya uygun bir boşta kalma kuralı tetiklenmeden sıra otomatik ilerlemez.",
  "Your selected stop and the new queue entry are saved together. The timer starts when you confirm.": "Seçtiğin durdurma koşulu ve yeni sıra girdisi birlikte kaydedilir. Zamanlayıcı onayladığında başlar.",
