  "Storage needs attention": "Depolamada işlem gerekiyor",
  "Open Home to collect rewards.": "Ödülleri toplamak için Ana Sayfayı aç.",
  "Collect rewards on Home": "Ana Sayfadan ödülleri topla",
  "Open food and gear": "Yiyecek ve ekipmanı aç",
  "Collect your rewards, then heal or restock equipped food before fighting again.": "Ödüllerini topla, sonra tekrar savaşmadan önce iyileş veya kuşanılmış yiyeceği yenile.",
  "Collect rewards, then free space in Inventory or Bank before continuing.": "Ödülleri topla, ardından devam etmeden önce Envanterde veya Bankada yer aç.",
  "Your planned stop condition was met. Collect rewards and review the next queued action.": "Planladığın durdurma koşulu gerçekleşti. Ödülleri topla ve sıradaki işlemi incele.",
  "Collect rewards to settle this activity and review the reason it stopped.": "Etkinliği tamamlamak ve durma nedenini görmek için ödülleri topla.",
  "Use filters for large collections. Locked or favorite gear should stay protected during bulk actions.": "Büyük koleksiyonlar için filtreleri kullan. Kilitli veya favori ekipmanlar toplu işlemlerde korunmalıdır.",
  "Your Account": "Hesabın",
  "Find character slots, preferences, your Game Guide and account-wide systems here.": "Karakter yuvalarını, tercihlerini, Oyun Rehberini ve hesap genelindeki sistemleri burada bul.",
  "The Help & Game Guide lets you revisit any unlocked topic whenever you want.": "Yardım ve Oyun Rehberi, açtığın konuları istediğin zaman tekrar incelemeni sağlar.",
  "Show locked topics": "Kilitli konuları göster",
  "Hide locked topics": "Kilitli konuları gizle",
  "Social & player profiles": "Sosyal ve oyuncu profilleri",
  "Party and Guild have separate sections. Party Chat appears only while you belong to a Party.": "Grup ve Lonca ayrı bölümlerdir. Grup Sohbeti yalnızca bir gruptayken görünür.",
  "Parties & weekly rewards": "Gruplar ve haftalık ödüller",
  "Create or join a persistent Party, find players and claim shared weekly rewards.": "Kalıcı bir grup oluştur veya katıl, oyuncu bul ve ortak haftalık ödülleri al.",
  "Reach Level 20": "Seviye 20'ye ulaş",
  "Find a Guild, use its Chat, and follow Quests and Projects under Activities.": "Bir Lonca bul, sohbetini kullan ve Etkinlikler bölümünden Görevler ile Projeleri takip et.",
  "Reach Level 7": "Seviye 7'ye ulaş",
  "Open Social. Party and Guild are separate tabs; a locked Party shows only its unlock requirement.": "Sosyal bölümünü aç. Grup ve Lonca ayrı sekmelerdir; kilitli Grup yalnızca açılma koşulunu gösterir.",
  "Open the Guild tab to enter your Guild or browse recruiting guilds. Guild Chat is inside your Guild.": "Loncana girmek veya üye arayan loncaları incelemek için Lonca sekmesini aç. Lonca Sohbeti loncanın içindedir.",
  "Party Chat appears only when you join a Party. Tap a player in a roster or advert to view their profile.": "Grup Sohbeti yalnızca bir gruba katıldığında görünür. Profilini görmek için listedeki veya ilandaki bir oyuncuya dokun.",
  "In Social → Party, create a Party or find one through Recruitment.": "Sosyal → Grup bölümünde bir grup oluştur veya Üye Arama üzerinden grup bul.",
  "While in a Party, My Party shows members and weekly progress. Claim ready rewards here; open details only when needed.": "Bir gruptayken Grubum, üyeleri ve haftalık ilerlemeyi gösterir. Hazır ödülleri buradan al; ayrıntıları yalnızca gerektiğinde aç.",
  "Use Recruitment to find players, Party options to manage invitations, and Chat to message your Party. Chat is hidden when you are not in a Party.": "Oyuncu bulmak için Üye Arama, davetleri yönetmek için Grup seçenekleri ve mesajlaşmak için Sohbet kullan. Grupta değilken sohbet gizlidir.",
  "Open Guild to find or join a Guild. Your Guild remains available even if Parties are locked.": "Lonca bulmak veya katılmak için Lonca bölümünü aç. Gruplar kilitli olsa bile Lonca kullanılabilir.",
  "After joining, use Home for the overview, Activities for Quests, Muster and Projects, and Guild Chat for messages.": "Katıldıktan sonra genel bakış için Ana Sayfa, Görevler, Seferberlik ve Projeler için Etkinlikler, mesajlar için Lonca Sohbetini kullan.",
  "Use PvE for bosses and Hall for upgrades and the Guild shop.": "Bosslar için PvE, yükseltmeler ve Lonca Mağazası için Salon bölümünü kullan.",
  "The dungeon matchmaking team uses 1 Tank, 2 Damage and 1 Support. It is separate from the persistent Party in Social.": "Zindan eşleştirme takımı 1 Tank, 2 Hasar ve 1 Destek rolünden oluşur. Bu takım, Sosyal bölümündeki kalıcı Gruptan ayrıdır.",
  "Data & Privacy": "Veriler ve Gizlilik",
  "Backups, save information and privacy.": "Yedekler, kayıt bilgileri ve gizlilik.",
  "Deleting your local save removes progress stored on this device.": "Yerel kaydı silmek bu cihazda saklanan ilerlemeyi kaldırır.",
  "Current activity": "Mevcut etkinlik",
  "Chat": "Sohbet",
  "Combat, activities and number display.": "Savaş, etkinlikler ve sayı gösterimi.",
  "Chat bar, language channel and emotes.": "Sohbet çubuğu, dil kanalı ve ifadeler.",
  "AFK details": "AFK ayrıntıları",
  "Auto-travel between queued activities": "Sıradaki etkinlikler arasında otomatik yolculuk",
  "Automatically switch between already-unlocked regions only after a safe queue handoff. Does not reset the AFK limit.": "Yalnızca güvenli sıra geçişinden sonra açılmış bölgeler arasında otomatik geçiş yapar. AFK sınırını sıfırlamaz.",
  "Available with VIP, VIP+ or Supporter. Free players can still queue activities in their current region.": "VIP, VIP+ veya Destekçi ile kullanılabilir. Ücretsiz oyuncular da mevcut bölgelerinde etkinlikleri sıraya alabilir.",
