  "After joining, open Projects to contribute and use guild chat to meet your guild.": "Katıldıktan sonra katkı yapmak için Projeleri aç ve lonca üyeleriyle tanışmak için sohbeti kullan.",
  "Open your roster and select an owned companion to equip.": "Yoldaş listeni aç ve kuşanmak için sahip olduğun bir yoldaşı seç.",
