  "ACCOUNT PRESTIGE": "HESAP PRESTİJİ",
  "Every profession activity and recipe has its own R50 record. The Hall combines those records across the account for achievements, titles and profile recognition only.": "Her meslek etkinliğinin ve tarifin kendine ait R50 kaydı vardır. Salon bu kayıtları hesap genelinde yalnızca başarımlar, unvanlar ve profil tanınması için birleştirir.",
