  "Open a profession to continue its strongest action or choose another R50 target.": "En güçlü etkinliğine devam etmek veya başka bir R50 hedefi seçmek için mesleği aç.",
  "No profession mastery has been recorded yet. Train gathering or crafting actions to begin filling the Hall.": "Henüz meslek ustalığı kaydedilmedi. Salonu doldurmak için toplama veya üretim etkinliklerini geliştir.",
