  "Reach Rank 50 on any profession activity or recipe to create your first permanent Mastered Record.": "İlk kalıcı Ustalık Kaydını oluşturmak için bir meslek etkinliğinde veya tarifte Derece 50'ye ulaş.",
  "Choose Profile Mastery Showcase": "Profil Ustalık Vitrinini Seç",
  "PRESTIGE, NOT POWER": "GÜÇ DEĞİL, PRESTİJ",
  "Prestige, not power": "Güç değil, prestij",
  "Mastery Hall achievements, the Masterwork Savant title and Profile showcase slots recognize completed mastery. They do not add another damage, yield, speed or account-wide multiplier.": "Ustalık Salonu başarımları, Masterwork Savant unvanı ve Profil vitrini yuvaları tamamlanan ustalığı gösterir. Ek hasar, verim, hız veya hesap genelinde çarpan vermez.",
  "Each member can add 1 Rally Mark per qualifying day. Target: roughly {participants} of {members} members qualifying on {days} days; everyone can help.": "Her üye uygun olduğu her gün 1 Seferberlik Nişanı kazandırabilir. Hedef: {members} üyeden yaklaşık {participants} kişinin {days} gün boyunca koşulları karşılaması; herkes katkı verebilir.",
  "Rally tiers: 35% / 70% / 100%. Completed Guild Projects earn +5% / +10% / +15% Hall Progress. Resets Monday 00:00 UTC.": "Seferberlik eşikleri: %35 / %70 / %100. Tamamlanan Lonca Projeleri +%5 / +%10 / +%15 Salon İlerlemesi kazandırır. Pazartesi 00.00 UTC'de sıfırlanır.",
  "{points}/{goal} today · {days}/{weekGoal} Rally days": "Bugün {points}/{goal} · Seferberlik günleri {days}/{weekGoal}",
  "{days}/{goal} Rally days · {points} weekly points": "Seferberlik günleri {days}/{goal} · {points} haftalık puan",
