  "Show fewer members": "Daha az üye göster",
  "No points means no verified Muster contribution has been recorded today. Playing does not always mean a qualifying receipt was recorded. Refresh to check recent activity.": "Puan yoksa bugün doğrulanmış Seferberlik katkısı kaydedilmemiştir. Oynamak her zaman uygun bir katkı kaydı oluşturmaz. Son etkinlikleri kontrol etmek için yenile.",
