  "Your combat and role-focused contribution both advance the guild boss.": "Hem savaş gücün hem de rolüne özel katkın Lonca Bossu ilerlemesini artırır.",
  "Previous weekly rewards": "Önceki haftalık ödüller",
  "This boss has rotated out. You can still claim earned milestones until the claim deadline.": "Bu bossun dönemi sona erdi. Kazandığın aşama ödüllerini son teslim tarihine kadar alabilirsin.",
  "Tank builds earn extra contribution from their protective stat profile. No blocked hits are fabricated.": "Tank dizilimleri koruyucu özelliklerinden ek katkı kazanır. Gerçekte engellenmeyen vuruşlar varmış gibi gösterilmez.",
  "Attack power is weighted more heavily this week. Other roles and companions still help.": "Bu hafta Saldırı Gücü daha fazla katkı sağlar. Diğer roller ve yoldaşlar da yararlıdır.",
  "Support contribution is based on server-side character stats and class, not fabricated healing events.": "Destek katkısı uydurma iyileştirme olaylarına değil, sunucudaki karakter özelliklerine ve sınıfına dayanır.",
