  "Choose how many recent World chat messages stay visible in the translucent bar above navigation. Tap the bar to open full chat.": "Gezinme menüsünün üstündeki saydam çubukta kaç Dünya sohbet mesajının görüneceğini seç. Tam sohbeti açmak için çubuğa dokun.",
  "CHOOSE HOW MANY RECENT WORLD CHAT MESSAGES STAY VISIBLE IN THE TRANSLUCENT BAR ABOVE NAVIGATION. TAP THE BAR TO OPEN FULL CHAT.": "GEZİNME MENÜSÜNÜN ÜSTÜNDEKİ SAYDAM ÇUBUKTA KAÇ DÜNYA SOHBET MESAJININ GÖRÜNECEĞİNİ SEÇ. TAM SOHBETİ AÇMAK İÇİN ÇUBUĞA DOKUN.",
