  "Text scaling follows your device setting up to the selected maximum. Reduced motion disables repeating combat and progress effects.": "Yazı ölçeği, seçilen üst sınıra kadar cihaz ayarını izler. Azaltılmış hareket, tekrarlanan savaş ve ilerleme efektlerini kapatır.",
  "Text scaling follows your device accessibility setting. Reduced motion disables repeating combat and progress effects.": "Yazı ölçeği cihazının erişilebilirlik ayarını izler. Azaltılmış hareket, tekrarlanan savaş ve ilerleme efektlerini kapatır.",
