  "Soft mint · cool teal accents": "Yumuşak nane · serin turkuaz vurgular",
  "Accent colors mark actions and selection. Green means success, amber caution, red danger, and violet special or premium content.": "Vurgu renkleri eylem ve seçimleri belirtir. Yeşil başarıyı, sarı uyarıyı, kırmızı tehlikeyi, mor özel veya premium içeriği gösterir.",
  "TEXT SCALING FOLLOWS YOUR DEVICE SETTING UP TO THE SELECTED MAXIMUM. REDUCED MOTION DISABLES REPEATING COMBAT AND PROGRESS EFFECTS.": "YAZI ÖLÇEĞİ SEÇİLEN ÜST SINIRA KADAR CİHAZ AYARINI İZLER. AZALTILMIŞ HAREKET TEKRARLANAN SAVAŞ VE İLERLEME EFEKTLERİNİ KAPATIR.",
