  "EXPORT A COPY OF MY ONLINE SAVE": "ÇEVRİMİÇİ KAYDIMIN BİR KOPYASINI DIŞA AKTAR",
  "Your account and gameplay progress are stored on VELDRYN servers. Your older local save stays on this device.": "Hesabın ve oyun ilerlemen VELDRYN sunucularında saklanır. Eski yerel kaydın bu cihazda kalır.",
  "YOUR ACCOUNT AND GAMEPLAY PROGRESS ARE STORED ON VELDRYN SERVERS. YOUR OLDER LOCAL SAVE STAYS ON THIS DEVICE.": "HESABIN VE OYUN İLERLEMEN VELDRYN SUNUCULARINDA SAKLANIR. ESKİ YEREL KAYDIN BU CİHAZDA KALIR.",
  "Offline progress remains on this device. Local progress cannot be uploaded as online rewards.": "Çevrimdışı ilerleme bu cihazda kalır. Yerel ilerleme çevrimiçi ödül olarak yüklenemez.",
  "OFFLINE PROGRESS REMAINS ON THIS DEVICE. LOCAL PROGRESS CANNOT BE UPLOADED AS ONLINE REWARDS.": "ÇEVRİMDIŞI İLERLEME BU CİHAZDA KALIR. YEREL İLERLEME ÇEVRİMİÇİ ÖDÜL OLARAK YÜKLENEMEZ.",
