  "BONUSES": "BONUSLAR",
  "A SINGLE VIEW OF MODIFIERS THAT ARE ACTUALLY ACTIVE IN GAMEPLAY RIGHT NOW. COLLECTION OWNERSHIP IS ACCOUNT-WIDE; SELECTED FAITH AND PERMANENT BOOST SOURCES FOLLOW THE ACTIVE CHARACTER.": "ŞU ANDA OYUNDA GERÇEKTEN ETKİN OLAN DEĞİŞTİRİCİLERİN TEK EKRANI. KOLEKSİYON SAHİPLİĞİ HESAP GENELİNDEDİR; SEÇİLEN İNANÇ VE KALICI GÜÇLENDİRMELER ETKİN KARAKTERİ İZLER.",
  "LESS TAKEN / CONSUMED": "DAHA AZ ALINAN / TÜKETİLEN",
  "EFFECTIVE INCREASE": "GEÇERLİ ARTIŞ",
  "NO PERMANENT GAMEPLAY MODIFIERS ARE ACTIVE ON THIS CHARACTER YET.": "BU KARAKTERDE HENÜZ ETKİN KALICI OYUN DEĞİŞTİRİCİSİ YOK.",
  "NO PERMANENT SOURCE IS CONTRIBUTING A BONUS YET.": "HENÜZ BONUS SAĞLAYAN KALICI BİR KAYNAK YOK.",
  "What counts here": "Burada neler sayılır",
  "THIS SCREEN REFLECTS THE SAME RUNTIME MULTIPLIER CALCULATION USED BY COMBAT, SKILLING, REWARDS AND OTHER SUPPORTED SYSTEMS. LOCKED COLLECTIBLES AND INACTIVE ENTITLEMENTS ARE NOT COUNTED. COLLECTION CAPS ARE ALREADY APPLIED BEFORE THE TOTALS ARE SHOWN.": "BU EKRAN SAVAŞ, BECERİ GELİŞTİRME, ÖDÜLLER VE DESTEKLENEN DİĞER SİSTEMLERDE KULLANILAN ÇARPAN HESABINI GÖSTERİR. KİLİTLİ KOLEKSİYONLAR VE ETKİN OLMAYAN HAKLAR SAYILMAZ. TOPLAMLAR GÖSTERİLMEDEN ÖNCE KOLEKSİYON SINIRLARI UYGULANIR.",
  "One claim per UTC day. Missing a day simply pauses the track—your progress never resets. Normal claims bank two hours of qualifying +10% activity time; milestone claims award account-wide premium currency.": "UTC gününde bir kez ödül alınabilir. Gün kaçırmak ilerlemeyi sıfırlamaz, yalnızca duraklatır. Normal ödüller uygun etkinlikler için iki saatlik +%10 güçlendirme biriktirir; aşama ödülleri hesaba premium para birimi verir.",
  "ONE CLAIM PER UTC DAY. MISSING A DAY SIMPLY PAUSES THE TRACK—YOUR PROGRESS NEVER RESETS. NORMAL CLAIMS BANK TWO HOURS OF QUALIFYING +10% ACTIVITY TIME; MILESTONE CLAIMS AWARD ACCOUNT-WIDE PREMIUM CURRENCY.": "UTC GÜNÜNDE BİR KEZ ÖDÜL ALINABİLİR. GÜN KAÇIRMAK İLERLEMEYİ SIFIRLAMAZ, YALNIZCA DURAKLATIR. NORMAL ÖDÜLLER UYGUN ETKİNLİKLER İÇİN İKİ SAATLİK +%10 GÜÇLENDİRME BİRİKTİRİR; AŞAMA ÖDÜLLERİ HESABA PREMİUM PARA BİRİMİ VERİR.",
