  "• SKILL XP: QUALIFYING SKILLING, CRAFTING, ALCHEMY AND FAITH XP.": "• BECERİ XP'Sİ: UYGUN BECERİ, ÜRETİM, SİMYA VE İNANÇ XP'Sİ.",
  "• Combat XP: character XP from normal hunts; it does not boost Gold, drops, pet chances or event/ranking rewards.": "• Savaş XP'si: normal avlardan gelen karakter XP'si; Altın, ganimet, evcil hayvan şansı veya etkinlik/sıralama ödüllerini artırmaz.",
  "• COMBAT XP: CHARACTER XP FROM NORMAL HUNTS; IT DOES NOT BOOST GOLD, DROPS, PET CHANCES OR EVENT/RANKING REWARDS.": "• SAVAŞ XP'Sİ: NORMAL AVLARDAN GELEN KARAKTER XP'Sİ; ALTIN, GANİMET, EVCİL HAYVAN ŞANSI VEYA ETKİNLİK/SIRALAMA ÖDÜLLERİNİ ARTIRMAZ.",
