  "These destinations are visible for roadmap clarity only. They do not accept contributions, consume resources or affect rankings yet. Guild Legacy will eventually extend the Guild Hall Trophy Room into a permanent seasonal history.": "Bu bölümler yalnızca yol haritasını göstermek için görünür. Henüz katkı kabul etmez, kaynak tüketmez veya sıralamaları etkilemez. Lonca Mirası ileride Lonca Salonunun Kupa Odasını kalıcı sezon geçmişiyle genişletecek.",
  "Asynchronous guild-versus-guild matchups with contribution objectives, fair brackets and no requirement for every member to be online together.": "Katkı hedefleri ve adil eşleşmeler içeren, tüm üyelerin aynı anda çevrimiçi olmasını gerektirmeyen eşzamanlı olmayan lonca karşılaşmaları.",
  "Longer guild encounters built around role contribution, shared boss progress and guild-wide completion rewards.": "Rol katkısı, ortak boss ilerlemesi ve lonca çapında tamamlama ödüllerine dayanan uzun lonca karşılaşmaları.",
  "Short rotating guild challenges with authored restrictions, score targets and cooperative mastery goals.": "Özel kısıtlar, puan hedefleri ve ortak ustalık amaçları içeren dönüşümlü kısa lonca mücadeleleri.",
