  "A permanent guild record of past seasons, raid clears, Guild vs Guild results, major Projects, trophies and notable guild milestones.": "Geçmiş sezonların, tamamlanan baskınların, lonca savaşlarının, büyük Projelerin, kupaların ve önemli lonca aşamalarının kalıcı kaydı.",
