  "Save new password": "Yeni şifreyi kaydet",
  "FALLEN KNIGHT REMATCH · Weekly boss rewards and progression updated.": "FALLEN KNIGHT RÖVANŞI · Haftalık boss ödülleri ve ilerleme güncellendi.",
  "Pack Instinct: +4% damage against enemies below 35% HP.": "Sürü İçgüdüsü: Canı %35'in altındaki düşmanlara +%4 hasar.",
  "Hamstring Pounce recharges 8% faster after defeating a weakened target.": "Zayıflamış bir hedef yenildiğinde Hamstring Pounce %8 daha hızlı yeniden hazır olur.",
  "Runic Guard: every 12s, owner takes 6% less damage from the next hit.": "Rün Muhafazası: Her 12 saniyede bir sahibinin sonraki vuruştan aldığı hasar %6 azalır.",
  "Rune Brace also grants a small follow-up shield after its second protected hit.": "Rune Brace, korunan ikinci vuruştan sonra küçük bir ek kalkan da sağlar.",
  "Flowing Current: owner's first ability after combat starts has 5% shorter cooldown.": "Akışkan Akım: Savaşın başında sahibinin ilk yeteneğinin bekleme süresi %5 daha kısadır.",
  "Silver Current grants an additional short Haste pulse after restoring class resource.": "Silver Current, sınıf kaynağını yeniledikten sonra kısa süreli ek bir Hız etkisi sağlar.",
  "Barkbreaker: attacks have a 12% chance to apply -3% Defence for 5s; non-stacking.": "Kabuk Kıran: Saldırıların 5 saniyeliğine Savunmayı %3 azaltma şansı %12'dir; birikmez.",
  "Deals 6% more companion damage to targets currently affected by defense reduction.": "Savunma azaltma etkisi altındaki hedeflere %6 daha fazla yoldaş hasarı verir.",
  "Flicker Sense: +8% unit accuracy against enemies currently casting.": "Titreşim Sezgisi: Büyü yapmakta olan düşmanlara karşı yoldaş İsabeti +%8.",
  "A successful interrupt shortens the next Lantern Snuff cooldown by 10%.": "Başarılı bir kesme, sonraki Lantern Snuff bekleme süresini %10 kısaltır.",
  "Oathkeeper: once per encounter, intercepts 8% of one hit dealt to owner.": "Yemin Koruyucusu: Her karşılaşmada bir kez sahibine gelen bir vuruşun %8'ini karşılar.",
  "After the shield breaks, the owner gains brief mitigation.": "Kalkan kırıldıktan sonra sahibi kısa süreli hasar azaltma kazanır.",
  "Veiled Edge: first unit hit against a new target has +10% crit chance.": "Örtülü Keskinlik: Yeni hedefe yapılan ilk yoldaş vuruşunda kritik şansı +%10.",
  "Gloamstep gains an additional execute bonus against critically wounded targets.": "Gloamstep, ağır yaralı hedeflere karşı ek bitirici bonus kazanır.",
  "Warm Light: every 15s the lowest-HP party member gains a 2% max-HP shield.": "Ilık Işık: Her 15 saniyede bir Canı en düşük grup üyesi, azami Canının %2'si kadar kalkan kazanır.",
  "Dawn Pinion may remove one additional minor debuff when used below 35% HP.": "Dawn Pinion, Can %35'in altındayken kullanılırsa ek bir küçük olumsuz etkiyi kaldırabilir.",
  "Echo Hunter: +5% damage against enemies with any player-applied debuff.": "Yankı Avcısı: Oyuncuların uyguladığı olumsuz etkilerden biri bulunan düşmanlara +%5 hasar.",
  "Echo Rend recharges faster while the priority target has multiple debuffs.": "Öncelikli hedefte birden fazla olumsuz etki varken Echo Rend daha hızlı yeniden hazır olur.",
  "Calibrated Shot: every 4th attack ignores 5% of target Defence.": "Ayarlı Atış: Her dördüncü saldırı, hedefin Savunmasının %5'ini yok sayar.",
  "Siege Bolt ignores an additional 3% Defence against high-HP targets.": "Siege Bolt, Canı yüksek hedeflere karşı ek %3 Savunmayı yok sayar.",
  "Remembered Route: first manual target swap each encounter gives unit +12% Haste for 4s.": "Hatırlanan Rota: Her karşılaşmada ilk elle hedef değiştirme, yoldaşa 4 saniyeliğine +%12 Hız verir.",
  "Memory Command grants a slightly stronger accuracy window after a manual target swap.": "Memory Command, elle hedef değiştirildikten sonra biraz daha güçlü bir İsabet bonusu sağlar.",
  "Reflected Oath: copies 25% of owner's current non-ultimate self-buff duration onto itself.": "Yansıyan Yemin: Sahibinin mevcut nihai olmayan kişisel güçlendirme süresinin %25'ini kendine kopyalar.",
  "A successful copied buff shortens the next Reflection cooldown without copying stat magnitude.": "Başarıyla kopyalanan bir güçlendirme, özellik değerini kopyalamadan sonraki Reflection bekleme süresini azaltır.",
  "A fast strike that gains extra finishing pressure against enemies below 30% HP.": "Canı %30'un altındaki düşmanlara ek bitirici baskı uygulayan hızlı bir vuruş.",
  "Sand Predator: basic attacks are more dangerous against weakened prey.": "Kum Avcısı: Normal saldırılar zayıflamış avlara karşı daha tehlikelidir.",
  "Bond 10 further strengthens Dune Stalker finishers.": "Bağ 10, Dune Stalker'ın bitirici saldırılarını daha da güçlendirir.",
  "Restores the lowest-HP ally and cycles slightly faster than a normal support active.": "Canı en düşük müttefiki iyileştirir ve normal bir destek yeteneğinden biraz daha hızlı yenilenir.",
  "Oasis Rhythm: slightly improves support tempo.": "Vaha Ritmi: Destek temposunu hafifçe artırır.",
  "Bond 10 improves the Djinnling’s restorative tempo.": "Bağ 10, Djinnling'in iyileştirme temposunu geliştirir.",
  "Creates a stronger shield that reflects a small share of absorbed damage.": "Emilen hasarın küçük bir bölümünü yansıtan daha güçlü bir kalkan oluşturur.",
  "Sunplate: slightly improves personal durability.": "Güneş Zırhı: Kendi dayanıklılığını hafifçe artırır.",
  "Bond 10 strengthens the Scarab’s reflective defense.": "Bağ 10, Scarab'ın yansıtmalı savunmasını güçlendirir.",
  "Creates a heavy royal barrier and reinforces the companion’s defensive stance.": "Güçlü bir kraliyet bariyeri oluşturur ve yoldaşın savunma duruşunu pekiştirir.",
  "Tyrant Guard: increased defensive stability.": "Tiran Muhafazası: Daha yüksek savunma kararlılığı.",
  "Bond 10 strengthens Crownward and the Heir’s defensive identity.": "Bağ 10, Crownward'ı ve Heir'in savunmacı rolünü güçlendirir.",
  "A cold finishing strike with extra pressure against wounded enemies.": "Yaralı düşmanlara ek baskı uygulayan soğuk bir bitirici vuruş.",
  "Winter Hunt: slightly faster combat tempo.": "Kış Avı: Biraz daha yüksek savaş temposu.",
  "Bond 10 sharpens the Rime Wolf’s finishing pressure.": "Bağ 10, Rime Wolf'un bitirici baskısını artırır.",
  "Restores the weakest ally and returns faster than most support actives.": "Canı en düşük müttefiki iyileştirir ve çoğu destek yeteneğinden daha hızlı yeniden hazır olur.",
  "Bell Rhythm: support cycles recover more quickly.": "Çan Ritmi: Destek döngüleri daha hızlı yenilenir.",
  "Bond 10 adds a small tempo bonus to the Bell Sprite.": "Bağ 10, Bell Sprite'a küçük bir tempo bonusu ekler.",
  "Raises a reinforced ward while the Golem’s resonant plating improves durability.": "Golem'in rezonanslı zırhı dayanıklılığı artırırken güçlendirilmiş bir koruma oluşturur.",
