  "Predatory Echo: stronger finishing pressure.": "Avcı Yankısı: Daha güçlü bitirici baskı.",
  "Bond 10 lets Wyrm’s Verdict cycle slightly faster.": "Bağ 10, Wyrm's Verdict'ın biraz daha hızlı yenilenmesini sağlar.",
