  "Obsidian Fang: slightly stronger basic attacks.": "Obsidyen Diş: Biraz daha güçlü normal saldırılar.",
  "Bond 10 adds finishing pressure to the Drakelet.": "Bağ 10, Drakelet'a bitirici baskı ekler.",
